mapper.delete:
DELETE
  FROM fnd10_book
 WHERE fnd10_std_date   = #{stdDate}
   AND fnd10_company_id = #{companyId}
   AND fnd10_fund_code_id IN ( SELECT fnd01_fund_code_id
                                 FROM fnd01_fund_code
                                WHERE fnd01_company_id = #{companyId}
                                  AND fnd01_icam_yn    = 'true' )

mapper.select:
SELECT fnd01_fund_code_id
  from fnd01_fund_code
 where fnd01_fund_cd = #{fundCode}
   and fnd01_company_id = #{companyId}

mapper.insert:
INSERT INTO fnd10_book
          ( fnd10_book_id
          , fnd10_std_date
          , fnd10_fund_code_id
          , fnd10_ast_class_tree_id
          , fnd10_company_id
          , fnd10_pur_amt
          , fnd10_eval_amt
          , fnd10_eval_pl_amt
          , fnd10_recv_amt
          , fnd10_note
          , fnd10_create_date
          , fnd10_creater
          , fnd10_detail_type
          , fnd10_item_cd
          , fnd10_item_group_cd
          , fnd10_item_group_nm
          , fnd10_market_cd
          , fnd10_market_nm
) VALUES (  #{p.bookId}
         ,  #{p.stdDate}
         ,  #{p.fundCodeId}
         ,  #{p.astClassTreeId}
         ,  #{p.companyId}
         ,  #{p.purAmt}
         ,  #{p.evalAmt}
         ,  #{p.evalPlAmt}
         ,  #{p.recvAmt}
         ,  #{p.note}
         ,  f_sysdate()
         ,  #{p.creater}
         ,  #{p.detailType}
         ,  #{p.itemCode}
         ,  #{p.itemGroupCode}
         ,  #{p.itemGroupName}
         ,  #{p.marketCode}
         ,  #{p.marketName}
         )

